import random
import math
from fractions import Fraction

def gaussian_elimination(A):
    m, n = len(A), len(A[0])
    rank = 0
    for i in range(n):
        pivot_row = None
        for j in range(rank, m):
            if A[j][i] != 0:
                pivot_row = j
                break
        if pivot_row is not None:
            A[pivot_row], A[rank] = A[rank], A[pivot_row]
            for j in range(n):
                if j == i:
                    A[rank][j] = Fraction(A[rank][j]).limit_denominator()
                else:
                    A[rank][j] = -A[rank][j] * A[pivot_row][i] // A[pivot_row][i]
            for j in range(m):
                if j != rank:
                    factor = A[j][i] * A[pivot_row][i] // A[pivot_row][i]
                    for k in range(n):
                        A[j][k] += -factor * A[rank][k]
            rank += 1
    return rank

def matrix_multiplication(A, B):
    m, n, p = len(A), len(B), len(B[0])
    C = [[Fraction(0) for _ in range(p)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][k] += A[i][j] * B[j][k]
    return C

def communication_complexity_rank(f, n):
    M_f = [[0 for _ in range(2**n)] for _ in range(2**n)]
    for i in range(2**n):
